begin;
do $release$
declare n public.gaas_vault_notes; run_id uuid; actor uuid;
begin
 select * into strict n from public.gaas_vault_notes where id='25931632-8994-4550-8333-290419fd9a15' for update;
 if n.content_hash<>'0d633df8d8db88fb1a512b483de2a3d04578e1f8a59ae4f25f507e48ecb88857' or exists(select 1 from gaas_wiki_pilot_documents where note_id=n.id) then raise exception 'insurance_note_changed';end if;
 select created_by into strict actor from growth_work_initiatives where id='03d2907e-2bb1-4c45-9b26-f3caf11480b4';
 insert into gaas_vault_sync_runs(vault_key,status,source,actor_id,completed_at,note_count,changed_count,deleted_count) values(n.vault_key,'completed','scoped-editorial-migration:seguros-map-alignment; authorized by Pablo',actor,now(),1,1,0) returning id into run_id;
 insert into gaas_vault_note_revisions(note_id,sync_run_id,content_hash,title,content_markdown,frontmatter) values(n.id,run_id,n.content_hash,n.title,n.content_markdown,n.frontmatter);
 update gaas_vault_notes set content_markdown=convert_from(decode('','base64'),'UTF8'),content_hash='1aa09a86bb668dafbd8c6bd906d042f16976206c4a354bd4730fc0d191da5f26',last_sync_run_id=run_id,indexed_at=now(),source_modified_at=now() where id=n.id;
end $release$;
commit;
